package cmd

import (
  "fmt"

  "github.com/spf13/cobra"
)

var (
  configPath string
  dryRun     bool
)

var rootCmd = &cobra.Command{
  Use:   "deployctl",
  Short: "Deploy services from a config file",
}

var applyCmd = &cobra.Command{
  Use:   "apply",
  Short: "Apply the config",
  RunE: func(cmd *cobra.Command, args []string) error {
    fmt.Printf("apply %s (dry run: %v)\n", configPath, dryRun)
    return nil
  },
}

func init() {
  rootCmd.Flags().StringVarP(&configPath, "config", "c", "deploy.yaml", "path to the config file")
  applyCmd.Flags().BoolVar(&dryRun, "dry-run", false, "print the plan without applying it")
  rootCmd.AddCommand(applyCmd)
}

func Execute() error {
  return rootCmd.Execute()
}

